+  /// Calendar days since the most recent walk (0 if it was today), null when
+  /// there is none. Same UTC midnights as the streaks.
+  static int? daysSinceLastWalk(Iterable<DateTime> walkStarts,
+      {required DateTime now}) {
+    if (walkStarts.isEmpty) return null;
+    final last =
+        walkStarts.map(_dateOnlyUtc).reduce((a, b) => a.isAfter(b) ? a : b);
+    return _dateOnlyUtc(now).difference(last).inDays;
+  }
