import 'package:flutter_test/flutter_test.dart';
import 'package:gambade/domain/gamification.dart';

// Test caché du banc dartlens : posé après l'essai, lancé sous TZ=Europe/Paris puis TZ=UTC.
void main() {
  DateTime d(int y, int m, int day, [int h = 12]) => DateTime(y, m, day, h);

  test('aucune balade : null', () {
    expect(
        Gamification.daysSinceLastWalk(const <DateTime>[],
            now: d(2026, 7, 1, 20)),
        isNull);
  });

  test('balade le jour même : 0', () {
    expect(
        Gamification.daysSinceLastWalk([d(2026, 7, 1, 8)],
            now: d(2026, 7, 1, 20)),
        0);
  });

  test("la plus récente compte, quel que soit l'ordre", () {
    expect(
      Gamification.daysSinceLastWalk(
        [d(2026, 6, 20), d(2026, 6, 29, 21), d(2026, 6, 25)],
        now: d(2026, 7, 1, 20),
      ),
      2,
    );
  });

  test('veille au soir, lendemain matin : un jour calendaire', () {
    expect(
        Gamification.daysSinceLastWalk([d(2026, 6, 30, 22)],
            now: d(2026, 7, 1, 7)),
        1);
  });

  test("passage à l'heure d'été : la journée de 23 h compte pour un jour", () {
    expect(
        Gamification.daysSinceLastWalk([d(2026, 3, 29, 0)],
            now: d(2026, 3, 30, 0)),
        1);
    expect(
        Gamification.daysSinceLastWalk([d(2026, 3, 27)], now: d(2026, 3, 30)),
        3);
  });

  test("passage à l'heure d'hiver : la journée de 25 h compte pour un jour",
      () {
    expect(
        Gamification.daysSinceLastWalk([d(2026, 10, 25, 23)],
            now: d(2026, 10, 26, 1)),
        1);
  });
}

